export const guideCategories=[['all','All topics'],['start','Getting started'],['wallet','Wallet & holding'],['runes','Runes & production'],['skills','Skills & recipes'],['combat','Combat & training'],['items','Items & economy'],['saving','Saves & troubleshooting'],['faq','Common questions']];
const article=(id,category,title,status,summary,paragraphs,extra={})=>({id,category,title,status,summary,paragraphs,...extra});
export const guideArticles=[
 article('starter-kit','start','Beginner Starter Kit: tools, equipment & supplies','live','Every character receives seven tools, four combat items, starter supplies and 50 Air Runes once.',[
  'Your kit is saved automatically when your character profile is created. Existing characters receive it once too. Signing in on another device never grants a second kit or resets your saved progress.',
  'Open Inventory → Tool Storage for seven reusable profession tools. Items & Gear holds four combat items and supply stacks. Equip the Bronze Sword, Wooden Shield, Leather Body and Leather Boots individually; each has its own saved slot. Equipped Gear shows the loadout and lets you unequip items.',
  'All starter items are account-bound and cannot be sold, transferred or dropped. Tools and combat equipment are reusable with unlimited durability. Supplies are intended to be consumed by eligible activities; profession execution remains a preview. No starter combat bonuses are assigned yet.',
  'The 50 Air Runes are credited directly to your separate Rune Inventory. They do not grant holding days, levels, or passive production eligibility. Passive production still requires a verified qualifying GP holding streak.',
  'Beginner Food is saved as a stack of five. Its exact activity-shortening effect and eligibility are pending, so consumption is disabled. The kit does not grant recipe inputs or other rune types beyond this list.',
  'New characters receive this kit instead of the old 120 prototype crafting supplies. Existing crafting supplies, owned equipment, XP and rune balances are preserved. The equipment collection statistic includes all seven starter tools and four starter combat items.'
 ],{table:{headers:['Item','Quantity','Requirement','Storage'],rows:starterKit.map(i=>[i.name,String(i.quantity),i.requirement,i.storage==='tools'?'Tool Storage':i.storage==='runes'?'Rune Inventory':'Items & Gear'])},action:'Inventory',keywords:'starter beginner kit free default net rake pickaxe hammer toolkit pot focus sword shield leather body boots bait seeds food air equipment durability'}),
 article('starter-kit-faq','faq','Where is my starter kit? Can I claim it again?','live','Find tools, supplies, equipped gear and runes in their own storage views.',[
  'Tools do not occupy item inventory spaces: open Inventory → Tool Storage. Unequipped combat gear, bait, seeds and food are in Items & Gear; equipped combat gear moves to Equipped Gear. Air Runes appear only in Rune Inventory.',
  'The kit is automatic and one-time per character. Refreshing, signing out, changing devices or consuming supplies does not refill it. Missing data should be refreshed; there is no reclaim button.',
  'Owning a tool does not bypass level, material or rune requirements, and does not activate preview activities. Beginner Food cannot be used until its effect is defined. Starter runes can be owned even when passive rune production is still locked.'
 ],{faq:true,action:'Inventory',keywords:'missing items tools inventory starter refill reclaim consume food equipment'}),
 article('universal-xp','skills','Universal XP Master V1: all levels 1–99','live','One shared profession curve, independent branch XP, and a separate combat curve.',[
  'All seven professions—Fishing, Farming, Mining, Smithing, Crafting, Cooking, and Enchanting—start at level 1 with 0 XP. Profession level 10 requires 184 XP, level 30 requires 1,428 XP, and level 99 requires 239,164 XP. Sharing a curve never shares XP between skills.',
  'All 21 active specializations start at branch level 1 with 0 XP. Branch level 10 requires 100 XP, level 50 requires 3,500 XP, and level 99 requires 125,000 XP. Unlocks do not grant XP. First branches open at parent level 10; the other two open at parent level 30.',
  'Attack, Strength, Defense, and Endurance each retain independent XP. Each reaches level 99 at 318,888 XP. Combat Level is derived from the four discipline levels and has no separate XP pool. Holding-based character status and legacy adventure XP are separate.',
  'Total XP is cumulative. XP to next in this table is the entire level interval; the player progress bar shows the actual XP remaining from your saved total. Level 99 is the level cap; extra earned XP is retained. The database derives levels from XP and identifies the curve version.',
  'Existing profession and combat XP is preserved. Earlier, replaced branch concepts remain archived with their saved XP; they are not automatically transferred into unrelated new branches. Enchanting now uses Elemental, Advanced, and Seasonal branches.',
  'These V1 values are draft balance. Profession and combat activities remain previews, and the current Steel Bars prototype awards adventure XP only. Future completed specialized activities award parent and selected-branch XP together, once per activity. One skill or service activity can run at a time; passive rune production continues separately.'
 ],{table:{headers:universalXpHeaders,rows:universalXpRows},action:'Skill Tree',keywords:'universal xp experience points leveling levels 99 239164 125000 318888 curve version enchanting'}),
 article('universal-unlocks','skills','All 21 specialization unlocks','live','Parent skill levels 10 and 30 unlock three independent branches per profession.',[
  'Every branch has its own level 1–99 and starts with 0 XP. Meeting a parent level requirement does not grant branch XP, bypass recipe requirements, or activate preview training.'
 ],{table:{headers:specializationHeaders,rows:specializationRows},action:'Skill Tree',keywords:'universal elemental advanced seasonal enchanting specialization branch unlock 10 30'}),

 article('start','start','Your first steps in Runelana','live','Create an account, explore the dashboard, and choose what to produce.',[
  'Create an email-and-password account, confirm your email when prompted, then sign in. Successful sign-in opens the player dashboard at /play. A wallet is separate from your account login.',
  'Open Settings to verify a Solana wallet and check its GP balance and holding history. Once at least one completed holding day is verified, Air Rune production starts automatically.',
  'Open Rune Production to divide your output among unlocked runes. Compare the Inventory column with your allocation, then confirm. Use Skill opens the activity selector, with seven professions, search, and Available / All filters. Skills in the left sidebar opens the Skill Tree with progression and specializations. Combat opens four independent combat disciplines, training previews, and encounter previews.'
 ],{action:'Settings',keywords:'begin beginner new play sign up signup registration tutorial'}),
 article('available','start','What can I do now?','live','A quick map of active features, game prototypes, and future content.',[
  'Available now: account sign-in, wallet verification, GP balance and historical holding checks, passive rune production, allocation controls, and a separate Rune Inventory. Skill, specialization, combat discipline XP, and current HP records are saved to your account.',
  'Account-saved prototypes: smithing steel bars, merchant delivery, game gold, adventure XP, equipment purchases, and equipping items. These follow your login across devices; player trading is not active.',
  'Preview only: 32 combat training activities, seven PvE encounters, combat gear/food effects, PvP, profession training, 50 activities each for Fishing V7, Farming V1, Mining V1, Cooking V1, Smithing V1, and Crafting V1, plus 5 other profession recipes, specialization training, advanced item buffs, commissioned services, player-to-player trading, live leaderboards, friends, and multiplayer chat. Browsing these previews spends no resources.'
 ],{keywords:'live available coming soon unfinished roadmap prototype preview'}),
 article('profile','start','Your character profile and account settings','live','My Profile shows your character dashboard; Settings manages your account and wallet.',[
  'My Profile has Character, Progression, Skills, and Collection tabs. View your verified GP balance, holding milestones, saved skill levels, and owned equipment. Edit Profile changes your adventurer name.',
  'The character illustration is a preview. Equipment slots show your saved starter combat loadout. Collection lets you equip or unequip each starter piece, and lists actual owned prototype equipment separately. Services Completed counts deliveries collected since account tracking began; older browser saves had no service counter.',
  'Open Settings from the sidebar or gear button for account management, wallet verification, balance refresh, unlinking, and detailed holding scans. The GP balance and sidebar player card open your character profile. The rune balance opens Rune Inventory; its plus button opens Rune Production. The player icon opens shortcuts including How It Works, Bank, Leaderboard, and Friends. Equipment in the sidebar opens your owned collection.'
 ],{action:'My Profile',keywords:'profile character settings edit name appearance avatar badges equipment collection'}),
 article('account','start','Accounts, email confirmation, and passwords','live','Use email to sign in; your wallet does not replace your player account.',[
  'Use Play Now to create an account, or choose Sign In if you already have one. Follow the confirmation email, then sign in on Runelana. Account settings lets you sign out or request a password reset.',
  'If confirmation opens localhost:3000, that is an old or incorrect redirect—not the game server. Return to www.runelana.com and try signing in; if your email is still unconfirmed, the confirmation link needs to be corrected by the site administrator. Do not share the full confirmation link, because it can contain your login token.',
  'If you forgot your password, choose the password-reset option on the sign-in form. Open the reset email and choose a new password.'
 ],{keywords:'login log in email safari localhost verification confirm reset password account settings'}),
 article('wallet','wallet','Verify a wallet and view GP','live','Link your own Phantom or Solflare wallet from Settings.',[
  'Sign in, open Settings, choose your wallet, and select Connect & verify wallet. Approve the ownership message in the wallet. This verification requests a signature, not a transaction, token transfer, or network fee. Never enter your recovery phrase or private key into Runelana.',
  'Phantom and Solflare are supported. On mobile, open Runelana in the wallet’s built-in browser and sign in there. If the wallet is not detected, use Check for wallet.',
  'One wallet can be linked to one player account at a time. Verification and balances follow your player account. The top-right GP display shows the linked wallet balance; select it to open My Profile.'
 ],{action:'Settings',keywords:'connect phantom solflare mobile extension signature fee seed phrase verification'}),
 article('gp-balance','wallet','Which GP balance counts?','live','Runelana checks the specific GP token in your verified Solana wallet.',[
  `The network is Solana mainnet. The GP mint is ${GP_MINT}. A token with the same name but a different mint does not count.`,
  'Balances are summed across matching GP token accounts owned by the verified wallet. Tokens held in staking, liquidity pools, escrow, custodial exchanges, or other wallets are not included in that wallet balance.',
  'Use Refresh GP balance in Settings after a transfer. Background scans also check linked wallets daily, even when you are signed out. The last-checked time matters: scans are not a live transaction feed. A failed scan shows unavailable or a last-known balance, rather than inventing a zero.'
 ],{action:'Settings',keywords:'amount 0 zero missing balance mint contract address token daily scan refresh staked pool exchange'}),
 article('holding','wallet','Longest holding streak and rune unlocks','live','Your best uninterrupted GP holding period determines your rune tier.',[
  'Holding time starts when GP first arrives in that wallet, whether by purchase or transfer. History checks reconstruct positive and zero-balance periods. Unlocks use the longest verified uninterrupted positive period, measured in completed days.',
  'Example: hold GP for 10 days, have zero for 3 days, then hold it for 5 more days. Your longest streak is 10 days—not 15 days and not the latest 5-day streak. A zero balance ends the current streak, but the historical best is retained.',
  'Settings also shows first receipt, current streak, total holding time, time without GP, and recent zero-balance gaps. Large histories can need several scans. Incomplete scans do not grant guessed days; the last verified result remains visible.',
  'The separate Observed GP holding period is a daily-scan counter. It can reset after a zero or a long scanning gap and can miss movements between scans. Rune unlocks use verified historical longest streaks instead.'
 ],{action:'Settings',keywords:'first purchase transfer longest uninterrupted streak days zero gap 10 3 5 scan history'}),
 article('wallet-changes','wallet','Changing, unlinking, or emptying a wallet','live','Eligibility follows the wallet linked to your profile.',[
  'Reverifying the same wallet preserves its history. Changing wallets requires verifying the new wallet and scanning its own history; holding time is not added across different wallets.',
  'Unlinking removes the wallet from the profile and pauses eligible production. Earned rune inventory is retained. A wallet change can reset allocation to Air, or to zero while awaiting eligibility. Review Rune Production afterward.',
  'For a still-linked wallet, reaching zero does not erase its best verified historical streak. Current rune eligibility uses that historical record, rather than requiring the present GP balance to stay positive.'
 ],{keywords:'unlink remove switch change wallet sold sell zero keep lose progress'}),
 article('unlocks','runes','All eight rune unlocks','live','Holding-based character status advances at each rune milestone.',[
  'Air, Mind, Water, Fire, Nature, Death, Blood, and Soul unlock at the milestones below. Character status is awarded from holding history; it is not a profession level or an additional XP requirement.',
  'Rarity describes the unlock progression. Runes are account-bound production materials and do not have a player-traded market price.'
 ],{table:{headers:['Rune','Rarity','Holding days','Character status'],rows:runeProgression.tiers.map(r=>[r.name,runeRarities[r.id],`${r.holdingDays} days`,`Level ${r.characterLevel}`])},action:'Rune Production',keywords:'air mind water fire nature death blood soul unlock level rarity common uncommon rare epic legendary'}),
 article('production','runes','Automatic rune production and offline earnings','live','Current production is a shared total of 10 runes per hour.',[
  'After the first verified holding-day unlock, production defaults to 10 Air Runes per hour. It runs passively, including while you are signed out, with no offline cap or Collect button.',
  'The current total is 10 runes/hour across all allocated types: 240 per day, 1,680 per week, or 7,200 in 30 days. Unlocking more types or holding more GP does not increase this total.',
  'Past holding history can unlock a tier immediately after verification, but it does not award runes for time before production became active. Partial progress toward the next rune carries forward.'
 ],{action:'Rune Production',keywords:'passive idle offline automatic always on hourly daily cap 10 240 1680 7200 retroactive'}),
 article('allocation','runes','Allocate production using your inventory','live','Compare what you own with what you want to make.',[
  'Open the Rune Production decision. Every rune row shows its inventory balance beside the minus/plus allocation controls. A small bar shows progress toward the next whole rune. Selecting a rune shows its details and current versus draft allocation.',
  'Assign whole hourly units to unlocked types. The total must equal 10 before Confirm Allocation becomes available. You can choose one type or several; for example, 6 Fire and 4 Water produces 6 Fire plus 4 Water per hour under today’s rates.',
  'Editing is only a draft until you confirm. Live inventory continues using the saved allocation. Reset Allocation restores the saved split, not your inventory. If another window changed the split, reset to the latest saved allocation and try again.',
  'Choose a split based on your planned recipes and stockpiles. A larger stockpile does not guarantee useful items, sales, or profit.'
 ],{action:'Rune Production',keywords:'allocate allocation minus plus confirm disabled reset inventory stock balance draft conflict'}),
 article('inventories','runes','Rune Inventory versus item Inventory','live','Runes, crafting supplies, and equipment are different resources.',[
  'Runes opens your account’s Rune Inventory. Air through Soul are stored separately from equipment and item materials. Earned runes cannot be traded or gifted.',
  'Inventory opens a full item grid with category filters and a separate item details panel. Select an item to view Details, Stats, or Sources. Owned equipment can be equipped here and is saved to your player profile. Empty slots are display spaces, not an inventory cap. Enchant, Move, and Drop are not available yet. Inventory shows steel bars, prototype crafting supplies, owned equipment, and the equipped item. The existing smithing and shop controls spend crafting supplies; they do not spend your eight typed rune balances.',
  'The production popup shows whole runes and fractional progress. If the count is still zero, check the progress bar, saved allocation, and eligibility. Unavailable data should be retried rather than assumed to mean an empty inventory.'
 ],{action:'Runes',keywords:'inventory items runes supplies separate fractional zero progress transfer gift trade'}),
 article('production-proposal','runes','Proposed slower high-tier production','proposal','These daily limits are a balancing proposal, not today’s rates.',[
  'The proposed model shares 10 capacity units per hour across every holding level. Higher-tier runes cost more capacity; fractional output accumulates. Each maximum below assumes all capacity goes to that one rune, so the limits cannot all be earned at once.',
  'With the proposal, full Soul allocation would produce 2 per day, 60 in 30 days, or 730 in a year after unlocking. A recipe needing 10 Soul would represent at least five days of full Soul production, before other ingredients and crafting time.',
  'Live production still uses 10 runes per hour. The proposed costs have not been activated or applied to existing balances.'
 ],{table:{headers:['Rune','Capacity / rune','Proposed max / day'],rows:runeProgression.tiers.map(r=>[r.name,String(proposedRuneCost(r.id)),String(240/proposedRuneCost(r.id))])},keywords:'proposed proposal rates capacity scarce scarcity soul 2 60 730 death 30 blood 12 fire 120'}),
 article('levels','skills','Three separate kinds of level','live','Holding status, adventure XP, and profession mastery are independent.',[
  'Character status comes from verified GP holding milestones and determines rune unlocks. It does not level up from smithing or service rewards.',
  'Adventure level is saved to your account. It starts at 1 and gains a level for each 60 adventure XP earned from completed activities.',
  'The seven profession levels and their specialization progress are account records. Fishing, Farming, Mining, Cooking, Smithing, and Crafting start at level 1 with 0 XP and use their saved overall and branch 1–99 XP curves. Enchanting uses the same Universal XP Master V1 thresholds. Profession training remains a preview; prototype adventure XP does not train these professions.'
 ],{action:'Skill Tree',keywords:'level xp experience character status adventure profession zero 0 60'}),
 article('combat-overview','combat','Combat progression: four disciplines and a derived Combat Level','live','Attack, Strength, Defense, and Endurance each start at level 1 with 0 XP; saved combat progress is separate from GP holding status.',[
  'Combat Level is floor((Attack + Strength + Defense + Endurance) / 4). It has no XP pool of its own. Attack 99 with Strength, Defense, and Endurance at 1 gives Combat Level 25, not 99.',
  'Holding GP unlocks runes and holding-based character status; it does not award combat XP. Profession XP and prototype adventure XP do not train combat either. Buying or equipping prototype gear gives no combat XP or assigned combat bonus.',
  'Open Combat from the left sidebar, Use Skill, Skill Tree, or My Profile. Your four XP totals, derived levels, base stats, and current HP are saved server-side. Account Stats still counts seven economic professions separately.',
  'Combat, travel, economic skills, services, and training are designed to share one active activity slot. Passive rune production continues independently. Combat training, travel, encounters, and PvP remain previews and cannot occupy a second activity slot.'
 ],{action:'Combat',keywords:'combat attack strength defense endurance level average gp holding adventure profession hp'}),
 article('combat-stats','combat','Combat stats, equipment, HP, and gear score','proposal','V1 defines draft base-stat formulas. Equipment bonus values, gear score weights, and combat resolution are not finalized.',[
  'Attack governs accuracy and weapon access; Strength governs damage potential; Defense governs resistance and armor access; Endurance governs base maximum HP. No player-allocated stat points are used.',
  'My Profile shows base stats only. The intended formulas add gear accuracy, power, resistance, or HP once a combat equipment master list defines those bonuses. Gear score is an equipment indicator, not a player level; its weights remain pending.',
  'Current HP is a saved encounter-state field and starts at base Max HP. Opening a profile never heals or resets it. Until combat gear is defined, the cap follows base Endurance HP. Increasing the cap does not automatically heal; decreasing it caps current HP. No battle or healing action is active yet.',
  'Future equipment restrictions must check relevant combat discipline levels and item requirements. Existing Smithing and Crafting equipment cannot be assigned combat stats just from its name.',
  'An encounter simulator must define attack intervals, hit probability, damage, healing, consumable use, and victory/retreat. The draft gives no tested success odds. Standard PvE is intended to avoid permanent loss of purchased equipment or wallet assets.'
 ],{table:{headers:['Stat','Draft formula / rule'],rows:[['Accuracy','10 + 1.10 × (Attack level − 1) + gear accuracy'],['Power','10 + 1.05 × (Strength level − 1) + gear power'],['Resistance','10 + 0.90 × (Defense level − 1) + gear resistance'],['Max HP','100 + 2 × (Endurance level − 1) + gear HP'],['Combat Level','floor((Attack + Strength + Defense + Endurance) / 4)'],['Current HP','Saved encounter state; starts at Max HP'],['Gear score','Normalized equipment bonuses; weights pending']]},action:'Combat',keywords:'accuracy power damage resistance maximum max hp health gear score formula stats points'}),
 article('combat-leveling','combat','Combat leveling V1: all 99 XP thresholds','live','Each independent discipline reaches level 99 at 318,888 XP. This is a separate curve from profession leveling.',[
  'The full V1 curve is saved in the database. Level 5 requires 90 XP; level 10 requires 246; level 30 requires 1,906; level 50 requires 8,959; level 75 requires 55,994; level 99 requires 318,888. Every discipline trains independently and retains overflow XP at level 99.',
  'At an illustrative constant 250 XP/hour, one discipline takes about 1,275.6 hours to reach 99. This is not a guaranteed training rate. Activities, level gates, travel, equipment, food, and balance simulations affect progression. The high-level curve is intentionally demanding and remains a balance proposal.',
  'New combat records begin at level 1 and zero XP. No existing adventure, profession, or GP holding progress is converted. Training and encounter XP settlement remain disabled.'
 ],{table:{headers:combatLevelHeaders,rows:combatLevelRows},action:'Combat',keywords:'combat xp curve threshold 1 99 318888 mastery time hours'}),
 ...combatDisciplines.map(d=>article(`combat-training-${d.id}`,'combat',`${d.name}: V1 combat training master list`,'preview',`Eight sessions award only ${d.name} XP after their timers complete.`,[
  'Requirements use the selected discipline level, not the derived Combat Level. Training timers and XP rewards are per completed session. Only one active training session is allowed, sharing the activity slot with travel, skills, services, and combat.',
  'Master Training lists 412 XP/hour in the source; 1,650 XP divided by 4 hours is 412.5. The listed figure, timer, and reward are preserved separately. Risk labels are qualitative, not success probabilities.',
  'Rune costs, specific equipment requirements, training risk effects, cancellations, refunds, and idempotent XP settlement need definition before activation. A missing requirement is not a promise that a session will be free. Browsing grants no XP and consumes nothing.'
 ],{table:{headers:combatTrainingHeaders,rows:combatTraining.filter(r=>r.disciplineId===d.id).map(combatTrainingRow)},action:'Combat',keywords:`combat training ${d.id} drills dummy sparring grandmaster trial xp risk`})),
 article('combat-encounters','combat','PvE encounter master list: seven draft encounters','preview','Encounter gates use derived Combat Level. Loot descriptions are possibilities, not guaranteed rewards.',[
  'Travel to the encounter location, prepare gear and food, choose a strategy, and commit the shared activity slot. The seven encounter timers range from 30 to 360 minutes.',
  'Suggested gear tiers are planning guidance, not assigned item stats or enforced loadout requirements. Combat outcome formulas, loot quantities and drop weights, travel behavior, strategy effects, and boss XP distribution are still pending.',
  'Standard PvE defeat should not permanently destroy purchased equipment or affect the wallet. Temporary injury, retreat time, and consumed supplies are design options, not active penalties.'
 ],{table:{headers:combatEncounterHeaders,rows:combatEncounters.map(combatEncounterRow)},action:'Combat',keywords:'pve forest bandit cave guardian ruined fortress deepwater serpent obsidian colossus abyssal leviathan eternal sentinel boss loot'}),
 article('combat-balance','combat','Combat food, PvP, and launch requirements','proposal','Combat gear, consumables, resolution, and rewards need additional master lists and simulations.',[
  'Cooking food currently proposes production-time reductions. Combat healing or survival effects must be designed separately; there is no finalized combat stacking rule. A cooking meal does not automatically heal or grant a combat bonus.',
  'The proposed first PvP mode is opt-in and asynchronous, with no wagered GP tokens or expensive items. Rankings, cosmetic titles, consent, and anti-collusion rules need definition. PvP is not active.',
  'Before launch, define combat gear loadouts and restrictions; a shared activity-job lifecycle; session strategy, timestamps, gear snapshots and food reservations; auditable results and seeds; versioned loot weights; and idempotent XP/inventory ledgers with cancellation/refund outcomes.',
  'Travel is intended to use the shared activity slot, but the final travel blocking rule still needs confirmation. Boss fights also need a rule for awarding XP to one chosen discipline or splitting it. Tune XP/hour for levels 1–30, 30–75, and 75–99, then simulate boss difficulty and reward demand.'
 ],{action:'Combat',keywords:'combat food heal stacking pvp opt in asynchronous consent no wager loot seed ledger travel balance pending'}),
 article('crafting-leveling','skills','Crafting leveling V1: overall and branch XP from 1 to 99','live','Overall mastery requires 239,164 XP; each independent branch reaches 99 at 125,000 XP.',[
  'Crafting follows the shared profession XP curves, starting at level 1 with 0 XP. Level 10 requires 184 XP, level 30 requires 1,428 XP, and level 99 requires 239,164 XP. The Crafting PDF does not supply a separate curve.',
  'Jewelry Making opens at Crafting level 10. Utility Crafting and Decorative Collectibles open at Crafting level 30. Each branch starts at level 1 with separate XP: branch level 10 requires 100 XP, level 50 requires 3,500 XP, and level 99 requires 125,000 XP. Both overall and branch gates apply.',
  'Existing Crafting and Jewelry Making XP is preserved. Former Artisan and Master Craftsman progress is archived rather than moved to unrelated branches. New branches begin with zero XP. Excess XP is retained at level 99.',
  'Crafting uses one active skill/service slot; passive runes continue independently. Saved levels and XP calculations are implemented. V1 recipe execution remains a preview.'
 ],{table:{headers:craftingLevelGuideHeaders,rows:craftingLevelGuideRows},action:'Skill Tree',keywords:'crafting xp leveling 99 239164 125000 jewelry utility decorative curve'}),
 article('crafting-master','skills','Crafting Master List V1: jewelry, equipment, and collectible displays','preview','50 recipes: 20 Standard, 10 Jewelry Making, 10 Utility Crafting, and 10 Decorative Collectibles.',[
  'Plant Fiber Cord is rune-free: Crafting level 1, 3 Plant Fiber, a Basic Crafting Kit, 8 minutes, yield 2, and 30 Crafting XP. The other 49 recipes have rune costs. Equipment is a separate requirement from the listed materials consumed per batch.',
  'Standard recipes award Crafting XP only. Branch recipes also award XP to their own specialization. Output yield does not multiply XP. Leather Strips yields 3 for 75 Crafting XP once per completed batch.',
  'Crafting assembles rods, nets, traps, jewelry, accessories, and collectible displays. Smithing makes metal tools, fittings, and bars. Enchanting adds magic separately. No speed, combat, or other equipment bonus is assigned by V1.',
  'Decorative displays consume their underlying trophy fish or other listed ingredients. Irreversible rare-item use must require confirmation before production begins. The preview flags these recipes; browsing never consumes or reserves an item.',
  'Some raw materials and tools still need upstream definitions. Raw Hide, Fish Oil, Rare Gem, Rare Timber, Feathers, and Deep-Sea Fiber require source reconciliation. Wooden Handle in Crafting is not silently renamed to the Smithing Wood Handle input. Matching names across draft catalogs do not make an item obtainable.',
  'Finished items may eventually trade for GP; runes remain account-bound. Item rarity, artwork/rights, ownership and inventory settlement, tradeability, cancellations, refunds, success rules, and audit records need definition before activation. V1 recipes remain previews.'
 ],{action:'Use Skill',keywords:'crafting master v1 materials jewelry utility decorative collectible consume confirmation equipment runes'}),
 ...craftingCategories.map(([id,name])=>article(`crafting-master-${id}`,'skills',`${name}: V1 Crafting master list`,'preview',`${craftingCatalog.filter(r=>r.category===id).length} recipes with materials, equipment, runes, minutes, yield, and independent XP.`,[
  'Both overall and branch level gates apply. Materials, runes, yield, and XP are per batch. Decorative recipes consume collectible inputs and require confirmation before irreversible rare-item production. These are previews, not active recipes.'
 ],{table:{headers:craftingGuideHeaders,rows:craftingCatalog.filter(r=>r.category===id).map(craftingGuideRow)},action:'Use Skill',keywords:`crafting ${id} material equipment minute yield xp confirmation`})),
 article('smithing-leveling','skills','Smithing leveling V1: overall and branch XP from 1 to 99','live','Overall mastery requires 239,164 XP; each independent branch reaches 99 at 125,000 XP.',[
  'Smithing follows the shared profession XP curves, starting at level 1 with 0 XP. Level 10 requires 184 XP, level 30 requires 1,428 XP, and level 99 requires 239,164 XP. The Smithing PDF does not supply a separate curve.',
  'Toolsmith opens at Smithing level 10. Artisan Equipment and Masterwork Forging open at Smithing level 30. Each branch starts at level 1 with separate XP: branch level 10 requires 100 XP, level 50 requires 3,500 XP, and level 99 requires 125,000 XP. Both overall and branch gates apply.',
  'Existing Smithing and Toolsmith XP is preserved. Former Armorsmith and Master Weaponsmith progress is archived rather than moved to unrelated branches. New branches begin with zero XP. Excess XP is retained at level 99.',
  'Smithing uses one active skill/service slot; passive runes continue independently. Saved levels and XP calculations are implemented. V1 recipe execution remains a preview.'
 ],{table:{headers:smithingLevelGuideHeaders,rows:smithingLevelGuideRows},action:'Skill Tree',keywords:'smithing xp leveling 99 239164 125000 toolsmith artisan masterwork curve'}),
 article('smithing-master','skills','Smithing Master List V1: bars, tools, equipment, and components','preview','50 recipes: 20 Standard, 10 Toolsmith, 10 Artisan Equipment, and 10 Masterwork Forging.',[
  'Every recipe consumes materials and runes per batch, including Copper Bar: level 1, 2 Copper Ore, 1 Air Rune, 12 minutes, yield 1, and 40 Smithing XP. Times follow the minute-based convention used by the other professions.',
  'Fittings and some components yield multiple items. XP is awarded once per completed batch, not multiplied by the output quantity. Precision Metal Hook yields 3 hooks for 250 Smithing XP and 140 Masterwork Forging XP.',
  'Smithing makes bars, metal tools, noncombat profession equipment, and components. Crafting handles nonmetal assembly, including rods, nets, and traps. Equipment modifiers, success probabilities, artwork, tradeability, and inventory caps are not assigned by this catalog.',
  'Some inputs match Mining or Farming draft outputs. Crafting V1 defines Reinforced Fiber and Woven Fiber recipes. Gemstone, Rare Gem, Rare Metal Ore, and Wood Handle still need exact upstream definitions; the Crafting Wooden Handle name is not automatically an alias. Rare Metal Ore Batch is not automatically interchangeable with Rare Metal Ore. A catalog reference does not grant an obtainable inventory item.',
  'The V1 Steel Bar recipe uses 2 Iron Ore, 2 Coal, and 2 Fire Runes, takes 35 minutes, yields 1 bar, and awards 120 Smithing XP. The separate playable Steel Bars prototype uses 20 crafting supplies, takes 2 minutes, yields 10 bars, and awards 10 adventure XP. It does not train Smithing.',
  'Training remains a preview. Execution still needs ownership, material/rune consumption and output ledgers, start/end times, equipment checks, and cancellation/refund rules. Browsing spends no resources.'
 ],{action:'Use Skill',keywords:'smithing master v1 materials smelting bars fittings tools equipment noncombat prototype'}),
 ...smithingCategories.map(([id,name])=>article(`smithing-master-${id}`,'skills',`${name}: V1 Smithing master list`,'preview',`${smithingCatalog.filter(r=>r.category===id).length} recipes with materials, rune costs, minutes, yield, and independent XP rewards.`,[
  'Requirements and costs apply per batch. Overall and branch level gates both apply. Production and item modifiers remain previews.'
 ],{table:{headers:smithingGuideHeaders,rows:smithingCatalog.filter(r=>r.category===id).map(smithingGuideRow)},action:'Use Skill',keywords:`smithing ${id} material equipment minute yield xp`})),
 article('cooking-leveling','skills','Cooking leveling V1: overall and branch XP from 1 to 99','live','Overall mastery requires 239,164 XP; each independent chef branch reaches 99 at 125,000 XP.',[
  'Cooking uses the approved shared XP curves with its own saved XP. It starts at level 1 with 0 XP. Level 10 needs 184 XP; level 30 needs 1,428 XP; level 99 needs 239,164 XP. Existing Cooking and branch XP is preserved.',
  'Everyday Chef opens at Cooking level 10. Artisan Chef and Master Chef open at Cooking level 30. Each starts at branch level 1 with separate XP. Branch level 10 needs 100 XP, level 50 needs 3,500 XP, and level 99 needs 125,000 XP. Both overall and branch requirements apply.',
  'Each completed batch awards Cooking XP. Specialized batches also award XP to their own branch. Yield is the number of servings; it does not multiply the XP reward. Excess XP is retained at level 99. Viewing another branch preserves all progress.',
  'Cooking uses the single active skill/service slot while passive rune production continues independently. XP calculation and saved progress are implemented; recipe execution remains a preview.'
 ],{table:{headers:cookingLevelGuideHeaders,rows:cookingLevelGuideRows},action:'Skill Tree',keywords:'cooking xp level 99 239164 125000 everyday artisan master chef curve'}),
 article('cooking-master','skills','Cooking Master List V1: meals, ingredients, and food effects','preview','50 recipes: 20 Standard, 10 Everyday Chef, 10 Artisan Chef, and 10 Master Chef.',[
  'All 50 recipes have rune costs, including Grilled Shrimp: Cooking level 1, 2 Shrimp, 1 Air Rune, 12 minutes, 2 servings, 40 Cooking XP, and a proposed 3% food time reduction. This replaces the earlier rune-free Cooking previews.',
  'Fisherman’s Lunchbox requires Cooking level 10 and Everyday Chef level 1: 2 Shrimp, 1 Wheat, and 1 Air Rune. It takes 22 minutes, yields 3 servings, and awards 90 Cooking XP plus 50 Everyday Chef XP once per batch.',
  'Food is consumed at the start of a chosen activity. It applies to that one activity only and cannot stack. The listed Speed percentage means a reduction in activity time: for example, 10% changes 100 minutes to 90 minutes. Food never changes rune generation, XP rewards, unlock requirements, or material costs.',
  'Artisan Chef meals are profession-specific. Their eligible professions are pending the separate CSV; names such as Miner’s Energy Bowl do not establish eligibility. No profession mappings or live food bonuses are inferred.',
  'Ingredients are recipe references, not proof of obtainable inventory. Some require new upstream Fishing/Farming definitions or acquisition recipes, including Legendary Spice and Sea Salt. Singular ingredients, bulk crates, and differently named herbs are not automatically treated as interchangeable.',
  'Cooking, food consumption, and meal rewards remain previews. Before launch, execution needs ownership and consumption ledgers, cooking start/end timestamps, eligibility checks, output servings, cancellation/refund rules, and balance testing. Browsing consumes nothing.'
 ],{action:'Use Skill',keywords:'cooking master v1 meal food speed time reduction ingredients servings shrimp chef pending eligibility stacking'}),
 ...cookingCategories.map(([id,name])=>article(`cooking-master-${id}`,'skills',`${name}: V1 Cooking master list`,'preview',`${cookingCatalog.filter(r=>r.category===id).length} recipes with ingredients, rune costs, minutes, servings, both XP rewards, and food time reductions.`,[
  'Draft costs and XP are per completed batch. Yield is servings, not an XP multiplier. All food effects remain previews. Artisan eligible professions and ingredient acquisition are pending. No effects stack or increase passive rune production.'
 ],{table:{headers:cookingGuideHeaders,rows:cookingCatalog.filter(r=>r.category===id).map(cookingGuideRow)},action:'Use Skill',keywords:`cooking chef ${id} ingredients food speed minutes servings xp`})),
 article('mining-leveling','skills','Mining leveling V1: overall and branch XP from 1 to 99','live','Overall mastery requires 239,164 XP; each independent branch reaches 99 at 125,000 XP.',[
  'Mining uses the approved Fishing/Farming XP thresholds, with its own saved XP. It starts at level 1 with 0 XP. Overall level 10 needs 184 XP; level 30 needs 1,428 XP; level 99 needs 239,164 XP.',
  'Ore Miner opens at overall Mining level 10. Gem Prospector and Rare Mineral Extractor open at level 30. Each starts at branch level 1 with independent XP. Branch level 10 needs 100 XP, level 50 needs 3,500 XP, and level 99 needs 125,000 XP.',
  'Every Mining activity awards overall Mining XP; specialization activities also award XP only to their own branch. Rewards are per completed activity, not multiplied by output yield. XP is cumulative, additional XP is retained at level 99, and branch switching never resets it.',
  'A branch change is allowed after the current activity completes or is canceled. Browsing a preview does not switch a running task. Mining occupies the single skill/service slot; passive rune production continues separately. The database derives levels from XP, while Mining training remains a preview.'
 ],{table:{headers:miningLevelGuideHeaders,rows:miningLevelGuideRows},action:'Skill Tree',keywords:'mining level xp 99 239164 125000 ore miner gem prospector rare mineral extractor switching curve'}),
 article('mining-master','skills','Mining Master List V1: ores, gems, and minerals','preview','50 activities: 20 Standard, 10 Ore Miner, 10 Gem Prospector, and 10 Rare Mineral Extractor.',[
  'Activities retain IDs MIN-001 through MIN-050. Every activity requires runes, including Copper Ore: Mining level 1, 1 Air Rune, a Bronze Pickaxe, 6 minutes, guaranteed yield 2, and 25 Mining XP per completion. This replaces the earlier rune-free Mining preview.',
  'Copper Vein Batch requires overall Mining level 10 and Ore Miner level 1: 3 Air Runes, an Iron Pickaxe, and 22 minutes. It yields 8 and awards 95 Mining XP plus 50 Ore Miner XP once, not eight times.',
  'You need both eligible access to each rune type through GP holding time and enough of every rune in inventory. A Mining level does not unlock a rune type. Runes remain account-bound.',
  'All listed times are minutes. Rune costs are per attempt; XP is per successful completion. Draft yields are guaranteed, including rare minerals. No random drops or invented tool speed bonuses are enabled. Pickaxes are reusable, not consumed.',
  'Mining supplies raw ores, gems, and minerals. Smithing smelts bars and forges metal tools; Crafting cuts gems and assembles accessories; Enchanting upgrades eligible items. Smithing V1 defines draft bar conversions and metal equipment recipes. Crafting V1 defines draft gemstone cutting recipes; execution and inventory links to equipment remain pending.',
  'Artwork references, ownership/tradeability, rarity, stack sizes, material uses, and cancellation/refund rules still need definition. Output IDs and labels are stored, but cache contents and conversions are not invented. Training is a preview; no runes, equipment, items, or XP change when browsing.'
 ],{action:'Use Skill',keywords:'mining master v1 ore gem mineral pickaxe reusable guaranteed yield time minute eligibility copper min-001 min-050 equipment'}),
 ...miningCategories.map(([id,name])=>article(`mining-master-${id}`,'skills',`${name}: V1 Mining master list`,'preview',`${miningCatalog.filter(r=>r.category===id).length} activities with stable IDs, requirements, rune costs, reusable equipment, guaranteed yields, and XP.`,[
  'Draft rune costs per attempt and XP per completed activity. Times are minutes; yield does not multiply XP. Standard rows have no branch requirement. Each branch checks both overall and branch levels. Rune access and sufficient inventory are additional requirements. Training remains a preview.'
 ],{table:{headers:miningGuideHeaders,rows:miningCatalog.filter(r=>r.category===id).map(miningGuideRow)},action:'Use Skill',keywords:`mining master v1 ${id} pickaxe yield rune guaranteed equipment xp`})),
 article('farming-leveling','skills','Farming leveling V1: overall and branch XP from 1 to 99','live','Overall level 99 requires 239,164 XP; each independent branch requires 125,000 XP.',[
  'Farming starts at level 1 with 0 XP. Overall level 10 needs 184 XP; level 30 needs 1,428 XP. Thresholds match Fishing V2, but Farming and Fishing never share XP.',
  'Crop Farming opens at overall Farming level 10. Herbalism and Rare Plant Cultivation open at overall level 30. Each starts at branch level 1 with independent XP. Branch level 10 needs 100 XP, level 50 needs 3,500 XP, and level 99 needs 125,000 XP.',
  'Both overall and branch level requirements apply. Switching preserves every branch’s XP. Additional XP is retained at level 99. The database derives levels from saved XP using these draft thresholds.',
  'Standard activities award overall Farming XP only. Branch activities award overall Farming XP plus XP to that branch. XP is per completed batch, not per harvested item. One skill or service task runs at a time; passive rune production continues separately. Training remains a preview.'
 ],{table:{headers:farmingLevelGuideHeaders,rows:farmingLevelGuideRows},action:'Skill Tree',keywords:'farming level xp 99 239164 125000 crop herbalism rare plant thresholds curve'}),
 article('farming-master','skills','Farming Master List V1: inputs, harvests, and rewards','preview','50 activities: 20 Standard, 10 Crop Farming, 10 Herbalism, and 10 Rare Plant Cultivation.',[
  'Wheat requires Farming level 1, a Basic Hoe, and one Wheat Seed. It costs no runes, takes 12 minutes, yields 3 Wheat, and awards 45 Farming XP per batch. Other Farming activities have rune costs.',
  'Bulk Wheat requires overall level 10 and Crop Farming level 1: 2 Water, an Iron Hoe, and 3 Wheat Seeds. It takes 35 minutes, yields 12, and awards 100 Farming XP plus 60 Crop Farming XP once per batch, not multiplied by twelve.',
  'Timers are in minutes. Inputs without an explicit multiplier represent one listed ingredient. Yield labels follow the PDF; crate contents and conversions into other item types are not defined.',
  'Seed, sapling, tool, and ingredient acquisition recipes are pending. Artwork, tradeability, rarity, seasons, and randomized yields are undecided. Farming is intended to supply Cooking, Crafting, Smithing, and Enchanting. Runes remain account-bound.',
  'Before training launches, the activity engine needs input ledgers, start/end timestamps, cancellation rules, and idempotent XP and item settlement. Previewing recipes spends nothing. Earlier Farming branch records are archived with their XP preserved.'
 ],{action:'Use Skill',keywords:'farming master v1 seeds saplings tools inputs yields harvest minutes wheat no runes dependency'}),
 ...farmingCategories.map(([id,name])=>article(`farming-master-${id}`,'skills',`${name}: V1 master list`,'preview',`${farmingCatalog.filter(r=>r.category===id).length} activities with levels, runes, equipment, inputs, yield, timers, and XP.`,[
  'Draft costs and rewards per completed batch. Training and acquisition recipes remain previews. Branch activities require both overall Farming and branch levels. Switching preserves progress.'
 ],{table:{headers:farmingGuideHeaders,rows:farmingCatalog.filter(r=>r.category===id).map(farmingGuideRow)},action:'Use Skill',keywords:`farming master v1 ${id} seed input yield equipment runes xp`})),
 article('fishing-leveling','skills','Fishing leveling V2: overall and branch XP from 1 to 99','live','Overall mastery requires 239,164 XP; each independent branch reaches mastery at 125,000 XP.',[
  'The saved V2 curves match the Fishing Level System V2 document. The overall curve is unchanged; the new branch curve is separate. Both remain draft balance values. Fishing begins at level 1 with 0 XP. The database derives your level from your total Fishing XP; levels cannot be edited independently. This curve is implemented, while Fishing activities and specialization training remain previews.',
  'XP required from level L to L+1 = round(15 × 1.075^(L−1)). Round each step to a whole XP, then add earlier steps to get the cumulative requirement. The curve increases gradually and can be rebalanced in a future version.',
  'Total XP never resets on level-up. With 20 total XP you are level 2: 5 of 16 XP into that level, with 11 XP remaining to level 3 at 31 total XP. Your Fishing bar shows this within-level progress, not level divided by 99.',
  'Commercial Fishing requires Fishing level 10 at 184 XP; Treasure and Trophy require level 30 at 1,428 XP. Each begins at branch level 1. Each branch uses its own saved XP total and the V2 branch curve: level 10 needs 100 XP, level 25 needs 500, level 50 needs 3,500, level 75 needs 22,000, level 90 needs 65,000, and level 99 needs 125,000. Specialization XP is separate from Fishing XP and never transfers between branches. Switching preserves each total; browsing a path neither selects it permanently nor awards XP. At 55 branch XP, you are branch level 7 with 4 XP remaining to level 8.',
  'Level 99 mastery begins at 239,164 XP. Overall and branch levels are capped at 99 and their bars stay full. Additional saved XP is retained; there is no level 100 requirement.',
  'Fishing XP is awarded for completed Fishing activities when training is enabled. Starting, cancelling, viewing previews, passive rune production, GP holding, and prototype Steel Bar rewards do not grant Fishing XP. The current draft recipe XP and times have not been activated.'
 ],{table:{headers:fishingLevelGuideHeaders,rows:fishingLevelGuideRows},action:'Skill Tree',keywords:'fishing leveling level experience xp formula round 1.075 239164 239,164 184 branch 125000 125,000 3500 3,500 independent switching retained mastery 99 1 10 30 next progress total cumulative'}),
 article('fishing-master','skills','Fishing Master List V7: requirements and rewards','preview','50 activities across Standard, Commercial, Treasure, and Trophy Fishing.',[
  'Standard Fishing contains 20 activities; Commercial, Treasure, and Trophy each contain 10. Use Skill → Fishing offers branch filters, search, and pagination. Fishing → Items and Guide show the full requirements. These are draft activities, not playable training yet.',
  'Every V7 Fishing activity consumes its listed rune combination when training is implemented. Shrimp requires Fishing level 1, 1 Air Rune, a Small Net, and 6 minutes for 25 Fishing XP. This replaces the earlier rune-free Fishing draft; other professions retain rune-free Basic recipes.',
  'Meet both the Fishing level and the branch level shown for specialization activities. Commercial begins at Fishing level 10; Treasure and Trophy at level 30. Each begins at branch level 1. Their XP is tracked independently. The Level System V2 supplies the separate branch XP curve. Equipment acquisition, bait quantities, locations, success rates, and crate contents remain unspecified.',
  'Main Fishing XP is earned on completion. Specialization activities also award the listed branch XP. For Shrimp Bundle x5, a completed 25-minute batch awards 90 Fishing XP and 55 Commercial XP in total—not five times those values. Standard activities have no branch XP reward.',
  'The existing Fishing 1–99 curve is unchanged: level 10 needs 184 cumulative XP and level 99 needs 239,164. Higher-level activities offer more XP per completion, but do not guarantee higher XP per hour or GP earnings. The listed XP is Runelana balance data, not official OSRS XP.',
  'Use “View OSRS item” to open the linked item page, not a direct image file. Bundle component links and base-fish links for trophy variants are visual references only, not identical finished items. Marine material matches are tentative. Entries marked “Original Runelana artwork needed” have no supplied art link. Item effects, catch probabilities, and market prices are not supplied.'
 ],{action:'Use Skill',keywords:'fishing master list v7 50 standard commercial treasure trophy batch bundle equipment bait xp rewards requirements shrimp 25 90 55'}),
 ...fishingCategories.map(([id,name])=>article(`fishing-master-${id}`,'skills',`${name}: V7 master list`,'preview',`${fishingCatalog.filter(r=>r.category===id).length} activities with levels, rune costs, equipment, timers, and XP.`,[
  'All XP values are per completed activity or batch. Activities remain previews; browsing this list consumes nothing.',
  id==='standard'?'Standard Fishing awards main Fishing XP only. All rows require the listed equipment and runes.':'Both Fishing and branch level requirements apply. Fishing XP and branch XP are separate; x5 bundle rewards are per batch, not per fish.'
 ],{table:{headers:fishingGuideHeaders,rows:fishingCatalog.filter(r=>r.category===id).map(fishingGuideRow)},action:'Use Skill',keywords:`fishing master v7 ${id} list equipment levels runes timer xp batch`})),
 article('skills','skills','Seven professions and their rune uses','preview','Open Skill Tree in the left sidebar to explore every profession.',[
  'Fishing, Farming, Mining, Smithing, Crafting, Enchanting, and Cooking have separate skill records. Cooking opens by default. Select another profession from the expanded sidebar.',
  'Skill Tree previews milestones and three specialization paths. Items lists draft recipe inputs, rune costs, outputs, required levels, durations, and XP. Services previews future commissions. Guide explains that profession and the rune economy.',
  'Primary rune uses define a profession’s main resource needs. Secondary uses apply to selected activities; neither list means every recipe consumes every listed rune. Enchanting uses all eight types, while other professions have smaller combinations.'
 ],{action:'Skill Tree',keywords:'fishing farming mining smithing crafting enchanting cooking seven primary secondary skill tree'}),
 article('rune-uses','skills','Which runes does each skill use?','preview','Primary and secondary uses describe the draft economy, not a universal recipe cost.',[
  'Primary uses are the profession’s main rune needs. Secondary uses appear in selected recipes. Fishing V7 specifies runes for every activity, including Shrimp. Farming Wheat and Crafting Plant Fiber Cord are rune-free. Each recipe names its own combination and quantities. These mappings support the planned training economy.'
 ],{table:{headers:['Skill','Primary runes','Secondary runes'],rows:[
  ['Fishing','Air, Water','Mind, Fire, Nature, Death, Blood, Soul'],['Farming','Water, Nature, Soul','Air, Mind, Fire, Death, Blood'],['Mining','Nature, Death, Blood','Air, Mind, Water, Fire, Soul'],['Smithing','Fire, Death, Blood, Soul','Air, Mind, Water, Nature'],['Crafting','Air, Mind, Nature, Blood, Soul','Water, Fire, Death'],['Enchanting','All eight rune types','None'],['Cooking','Water, Fire, Nature, Soul','Air, Mind, Death, Blood']
 ]},action:'Skill Tree',keywords:'mapping rune usage primary secondary fishing farming mining smithing crafting enchanting cooking'}),
 article('rune-purposes','runes','What is each rune used for?','preview','Each rune has a distinct purpose in the planned recipe economy.',[
  'These uses guide recipe design. They do not activate spells, buffs, or profession training yet. Current recipe combinations can be inspected under Skills → Items.'
 ],{table:{headers:['Rune','Purpose'],rows:[['Air','Precision and movement'],['Mind','Knowledge and technique'],['Water','Growth and preservation'],['Fire','Heat and transformation'],['Nature','Growth and refinement'],['Death','Dangerous materials and dark magic'],['Blood','Powerful equipment and rare materials'],['Soul','Legendary and prestige creations']]},keywords:'air mind water fire nature death blood soul purpose uses magic spells buffs'}),
 article('specializations','skills','Specializations and path previews','preview','Commercial Fishing, Crop Farming, Ore Miner, Everyday Chef, Toolsmith, and Jewelry Making open at level 10. Their other branches open at level 30.',[
  'Fishing V7: Commercial requires Fishing level 10 (184 total XP); Treasure and Trophy require level 30 (1,428 total XP). Each branch starts at level 1 with 0 branch XP. Meeting a level requirement does not activate specialization training.',
  'Cooking V1 opens Everyday Chef at overall level 10 and Artisan Chef/Master Chef at 30, with independent branch XP. Smithing opens Toolsmith at 10 and Artisan Equipment/Masterwork Forging at 30. Crafting opens Jewelry Making at 10 and Utility Crafting/Decorative Collectibles at 30. You can view every path and inspect example unlocks.',
  'Viewing or switching a preview does not choose a permanent specialization, consume runes, or award XP. Fishing, Farming, Mining, Cooking, Smithing, and Crafting branches begin at level 1 with zero XP; Enchanting’s Elemental, Advanced, and Seasonal branches also start at level 1 under Universal XP Master V1. The earlier Fishing branches are archived, with their saved XP preserved rather than transferred to an unrelated path. Training paths and their item benefits are still planned.'
 ],{action:'Skill Tree',keywords:'specialization path master chef artisan everyday level 30 select choose reset'}),
 article('recipes','skills','Basic, Intermediate, and Advanced recipes','preview',`${fishingCatalog.length} Fishing V7 activities and ${farmingCatalog.length} Farming V1 activities, ${miningCatalog.length} Mining V1 activities, ${cookingCatalog.length} Cooking V1 recipes, ${smithingCatalog.length} Smithing V1 recipes, ${craftingCatalog.length} Crafting V1 recipes, and ${recipes.filter(r=>!['fishing','farming','mining','cooking','smithing','crafting'].includes(r.skill)).length} other profession recipes are previews.`,[
  'Fishing V7, Mining V1, Cooking V1, and Smithing V1 require runes on every activity. Farming V1 Wheat, Crafting V1 Plant Fiber Cord, and some Enchanting previews are rune-free. Processing recipes may still need ordinary materials.',
  'Intermediate activities use Common and Uncommon runes. Advanced recipes combine at least one Rare, Epic, or Legendary rune with other rune types and materials. Common and Uncommon runes still matter in late-game recipes.',
  'Fishing, Farming, Mining, Cooking, Smithing, and Crafting each use their 50-activity master lists. Each other profession has five draft recipes: two Basic, two Intermediate, and one Advanced. Their costs, timings, XP, levels, and outputs are balancing proposals. The catalog is viewable now, but training and crafting these recipes are not activated. An unset cost is not a free recipe.'
 ],{action:'Skill Tree',keywords:'recipe recipes basic intermediate advanced no runes free materials ingredients costs quantities draft 35'}),
 article('prestige','skills','Legendary materials and collectible creations','preview','Prestige is intended to come from finished creations, not stored runes.',[
  'Soul is a Legendary-tier resource, but the rune itself is an account-bound crafting material. Finished weapons, equipment, seasonal goods, and rare crafted items are the intended collectibles.',
  'The draft seasonal enchantment requires level 85 Enchanting, 24 hours of crafting, 10 Soul, 1 Blood, 2 Mind, a Prestige Amulet, and 2 Moonherbs. The materials have their own upstream crafting requirements.',
  'Not every advanced recipe requires Soul. For example, the draft Legendary Armor recipe uses Blood, Fire, and Nature alongside steel and a Shadow Crystal. All these advanced recipes remain previews.'
 ],{action:'Skill Tree',keywords:'prestige legendary collectible seasonal enchantment weapon armor soul 10 mastery'}),
 article('activities','items','Current smithing and merchant service','prototype','These playable activities save progress to your account.',[
  `Use Skill opens a separate activity-selection window. Choose Smithing and the playable Steel Bars row to spend ${activities.smith.cost} crafting supplies, wait ${activities.smith.duration/60000} minutes, then collect ${activities.smith.bars} Steel Bars and ${activities.smith.xp} adventure XP.`,
  `Provide Service starts a merchant delivery: wait ${activities.service.duration/1000} seconds, then collect ${activities.service.gp} game gold and ${activities.service.xp} adventure XP. No crafting supplies are required.`,
  'Only one activity can run at a time. Its timer can finish while you are away, but rewards require Collect. Cancel returns spent crafting supplies. Passive rune production continues independently and does not occupy this activity slot.',
  'New accounts start with 120 crafting supplies. There is no current control for replenishing those prototype supplies. Merchant delivery remains available when supplies run out.'
 ],{action:'Use Skill',keywords:'smith steel bars merchant delivery service collect reward timer cancel busy supplies 20 120 seconds'}),
 article('currencies','items','Wallet GP versus game gold','live','The header and Bank intentionally show different balances.',[
  'The top-right header shows on-chain GP in your verified Solana wallet. Holding history for that token unlocks rune production.',
  'Bank shows game gold earned from prototype merchant services. Although the prototype labels it GP, it has no real-money value and does not transfer into your crypto wallet. It does not count toward holding history.',
  'Crafting supplies and typed runes are separate resources from both balances. Today’s equipment shop spends crafting supplies, not your on-chain GP.'
 ],{action:'Bank',keywords:'gp gold currency bank header balance money withdraw cash wallet 40 difference'}),
 article('market','items','Equipment, Collection, and the future marketplace','prototype','Equipment is account-saved; player trading is not live.',[
  'Marketplace lets you buy prototype equipment with crafting supplies. Buying equips the item. Collection shows owned items and lets you equip them again without repurchasing.',
  'There is no active player-to-player trading, GP payment settlement, listing, or commissioned-service marketplace. The planned economy would sell finished goods and services for GP, while runes remain account-bound.',
  'A rune allocation or rare recipe does not guarantee a sale or a valuable item. Future value should depend on player demand. Prototype equipment and preview prices are not promises of on-chain value.'
 ],{action:'Marketplace',keywords:'market marketplace buy sell trading trade equip equipment collection price profit demand commission'}),
 article('social','items','Leaderboards, friends, and private notes','preview','Shared rankings and multiplayer messaging are not connected yet.',[
  'Homepage adventurer rankings are illustrative. The dashboard leaderboard shows a placeholder while shared rankings are being developed. Friends and multiplayer chat are also not connected.',
  'The game log shows local activity messages. Notes are private to the current view, not sent to other players. They are held only for the current dashboard session and can disappear on reload or navigation.'
 ],{keywords:'leaderboard friends chat messages multiplayer notes public private rankings'}),
 article('account-stats','saving','How My Profile account stats are counted','live','Account stats are saved and reconciled with your account, equipment, profession progress, services, and verified wallet history.',[
  'Member Since is the original account creation date. Skills Trained counts professions with earned XP, completed activities, or recorded training time. The starting level of a skill does not count as training.',
  'Equipment Collected counts distinct equipment currently in your saved collection, including imported equipment. Equipping or buying an already owned item does not add another. Runes, steel bars, crafting supplies, and appearance previews are excluded.',
  'Services Completed counts collected merchant-service rewards from cloud tracking onward. Starting or canceling a task does not count. Repeated collection requests cannot add another completion. Historical browser-only service totals were not recorded.',
  'Total Holding Time adds all verified periods with positive GP and excludes zero-balance gaps. Current Streak is the uninterrupted period at the last verified chain checkpoint. Best GP Streak is the longest uninterrupted period and determines rune unlocks. The display includes hours and the checkpoint time; it does not assume GP remained in the wallet after that scan.',
  'Missing holding history is shown as unknown, never as zero. A stale scan is labeled last known. Unlinking or changing a wallet clears the old wallet’s holding stats until the new history is verified. Stats refresh when their source records change, when My Profile opens, and during regular profile refreshes.'
 ],{action:'My Profile',keywords:'account stats member since trained skills equipment collected services completed total holding current best longest streak zero unknown'}),
 article('saves','saving','What is saved, and where?','live','Your profile, equipment, resources, and activity progress follow your login.',[
  'Account-saved: verified wallet link, GP snapshots and holding history, rune inventory and saved production allocation, and skill/specialization records. Sign into the same account to access those records on another device.',
  'Account-saved: equipment, collected items, steel bars, crafting supplies, game gold, adventure XP, and the active activity. Changes save before appearing as successful. Open tabs refresh periodically and when you return. If another device made a newer change, its progress loads before you try again.',
  'Existing players: your first visit imports the original browser save once. Visit from your original browser first; later devices use the account save and cannot overwrite it with an older local copy. The original browser copy is retained. Old service totals were not recorded, so the counter starts at zero. Game log and notes remain session-only.'
 ],{keywords:'save saved storage offline device browser refresh reset sync lost missing progress account'}),
 article('troubleshooting','saving','When data is loading, stale, or unavailable','live','Check your session, the last scan, and whether the feature is active.',[
  'If GP appears wrong, open Settings and check the linked wallet, mint, and last-checked time, then refresh. A short cooldown prevents repeated refreshes. If no provider is detected on mobile, open the site in your wallet browser.',
  'If holding history is pending, let the scan complete and refresh later. Long histories may take several scans. If a request fails, Retry loads the last verified server data; a service outage does not prove your balance is zero.',
  'If Confirm Allocation is disabled, ensure a verified holding day has unlocked production, the draft totals exactly 10, and no save is in progress. Locked rune rows cannot receive allocation.',
  'All seven professions begin at level 1 with 0 XP under Universal XP Master V1. If XP does not increase or a recipe has no Start button, profession training is still a preview. Current smithing rewards adventure XP, not profession XP.'
 ],{action:'Settings',keywords:'error unavailable stale retry loading pending failed disabled confirm button zero start not working'}),
];
const faq=(id,category,title,answer,keywords='')=>article(id,category,title,'faq',answer,[answer],{faq:true,keywords});
export const guideFAQs=[
 faq('faq-combat-gp','combat','Does holding GP or buying a sword increase my Combat Level?','No. Combat Level comes from four independently trained discipline levels. GP holding status, profession XP, prototype adventure XP, and equipment purchases do not award combat XP. Gear bonuses are not configured yet.','combat gp gear sword buy'),
 faq('faq-combat-99','combat','Why would Attack 99 only give Combat Level 25?','Combat Level is the rounded-down average of Attack, Strength, Defense, and Endurance. With levels 99, 1, 1, and 1, the average is 25.5 and the displayed Combat Level is 25.','combat average 99 25'),
 faq('faq-combat-start','combat','Why can’t I start combat training or a boss fight?','Combat V1 is a master-list preview. Your independent XP and HP records are saved, but training settlement, risk effects, equipment rules, combat outcomes, and loot are not active. Viewing level eligibility does not start a job.','combat start disabled preview boss'),
 faq('faq-wallet','start','Do I need a wallet to create an account?','No. Sign in with email and password. A verified wallet with qualifying GP history is needed for rune production, not account creation.','signup wallet login'),
 faq('faq-free','skills','Can I play without GP or runes?','You can create an account, browse the dashboard, and use prototype activities. Fishing V7 requires runes even for Shrimp. Other professions still have rune-free Basic recipes; profession training is not live yet.','free beginner basic'),
 faq('faq-buy','wallet','Does receiving GP by transfer count?','Yes. Purchases and incoming transfers both count toward holding time while the wallet has a positive balance.','purchase buy swap transfer'),
 faq('faq-streak','wallet','What if my wallet goes to zero?','The current streak ends, but your longest verified historical streak is retained. Ten days held, three days empty, then five days held still gives a longest streak of ten days.','sell reset days'),
 faq('faq-offline','runes','Will runes keep producing if I close the game?','Yes, once eligible production is active. It continues with your saved allocation while you are away, with no offline cap or manual collection.','offline afk passive logout'),
 faq('faq-collect','runes','Do I need to collect runes?','No. Runes enter Rune Inventory automatically. The Collect button applies to completed prototype smithing or merchant-service activities.','claim collect automatic'),
 faq('faq-more','runes','Does holding more GP increase my production?','No. Today the shared output is fixed at ten runes per hour. Holding milestones unlock more rune types; they do not increase the total output.','capacity boost balance'),
 faq('faq-confirm','runes','Why can’t I confirm my allocation?','Production must be unlocked, allocated only to unlocked types, and total exactly ten. Finish any pending save. If another window changed your split, use Reset Allocation before trying again.','disabled allocation save conflict'),
 faq('faq-zero','runes','Why is my rune inventory still zero?','Check that production is active and that the rune has a saved allocation above zero. Whole-rune counts stay at zero until one finishes; the small bar shows fractional progress.','fraction partial inventory'),
 faq('faq-soul','runes','Is Soul production already limited to two per day?','No. Two Soul per day is the proposed rate at full allocation. Current live production remains ten runes per hour across your allocated types.','proposal legendary 2 daily'),
 faq('faq-trade','items','Can I trade, gift, or sell my runes?','No. Runes are account-bound materials. The planned marketplace is for finished items and services; player trading is not active yet.','transfer send sell marketplace'),
 faq('faq-gold','items','Why does Bank GP differ from my wallet balance?','Bank holds account-saved game gold from services. The header shows on-chain GP in your verified wallet. Game gold cannot be withdrawn and does not unlock runes.','balance withdraw money header'),
 faq('faq-crafting-runes','skills','Can I train Crafting without runes?','The V1 Plant Fiber Cord recipe needs no runes. All other listed Crafting recipes require runes, plus materials and equipment. These recipes are previews; production is not activated.','crafting free cord basic'),
 faq('faq-crafting-collectibles','skills','Does a trophy display keep the original fish?','No. A display recipe consumes the underlying trophy fish or listed collectible ingredients. Confirmation is required before irreversible rare-item use when production is enabled. Browsing the current preview consumes nothing.','crafting trophy collectible consume confirmation'),
 faq('faq-crafting-bonuses','skills','Will crafted jewelry or a fishing rod improve my stats?','No bonus is currently assigned. Profession equipment may gain tested speed benefits later, and Enchanting adds magic separately. Crafting V1 specifies recipes and requirements, not combat or equipment modifiers.','crafting equipment bonus jewelry rod'),
 faq('faq-crafting-branches','skills','What happens to my old Crafting branches?','Jeweler XP stays with Jewelry Making, which opens at Crafting 10. Utility Crafting and Decorative Collectibles open at 30 with independent zero XP. Old Artisan and Master Craftsman progress is archived intact. Switching preview branches never spends or transfers XP.','crafting branch jewelry artisan archived'),
 faq('faq-smithing-yield','skills','Does forging three fittings award triple XP?','No. Materials and runes are charged per batch, and the listed XP is awarded once per completed batch. Yield only determines how many items are produced. V1 training is still a preview.','smithing yield fittings batch xp'),
 faq('faq-smithing-tools','skills','Do Smithing tools grant combat or speed bonuses?','These are profession tools and noncombat equipment. Attack, defense, speed, and yield modifiers are not assigned by Smithing V1, and no such bonus is active.','smithing tool equipment modifier speed combat'),
 faq('faq-smithing-materials','skills','Can I obtain every Smithing material now?','No. Matching names in draft Mining or Farming catalogs do not make those items obtainable. Several upstream inputs still need definitions, and V1 production is not activated.','smithing materials source rare metal ore wood handle'),
 faq('faq-cooking-food','skills','Can I stack meals or increase rune production with food?','No. Cooking V1 food is consumed at the start of one chosen activity and reduces only that activity’s time. It cannot stack, and does not change passive rune generation, XP, unlocks, or ingredient costs. Food consumption is still a preview.','cooking food stack speed passive rune xp'),
 faq('faq-cooking-artisan','skills','Which profession can use an Artisan Chef meal?','The eligible profession must come from the recipe CSV. Those mappings are pending, so a meal name alone does not grant a profession bonus. The proposed reduction is shown for planning, but no food bonus is active.','cooking artisan eligibility profession pending csv'),
 faq('faq-cooking-servings','skills','Does cooking multiple servings multiply the XP?','No. Fisherman’s Lunchbox yields 3 servings and awards 90 Cooking XP plus 50 Everyday Chef XP per completed batch, not three times those amounts. Each branch maintains its own XP.','cooking servings yield batch xp lunchbox'),
 faq('faq-cooking-ingredients','skills','Where do I get every Cooking ingredient?','Some ingredients appear in the Fishing/Farming draft catalogs; others still need upstream definitions or acquisition recipes. Ingredient references do not imply an item is obtainable today. Cooking training and ingredient consumption remain previews.','cooking ingredient acquisition sea salt legendary spice missing'),
 faq('faq-mining-runes','skills','Can I mine Copper Ore without runes?','No. Mining V1 replaces the earlier rune-free Mining preview. MIN-001 Copper Ore requires 1 Air Rune, eligible access to Air through GP holding time, Mining level 1, and a Bronze Pickaxe. Training remains a preview.','mining copper air free access eligibility min-001'),
 faq('faq-mining-tools','skills','Are pickaxes consumed or do they give speed bonuses?','Mining pickaxes are reusable. Smithing V1 includes draft pickaxe recipes; acquisition and equipment effects are not yet active. No speed bonus is assumed or enabled by this master list.','mining pickaxe tool equipment speed reusable consumed'),
 faq('faq-mining-yields','skills','Are rare Mining drops random, and does yield multiply XP?','The V1 draft guarantees the listed output quantities. XP is awarded once per completed activity, not once per item. Copper Vein Batch yields 8 and awards 95 Mining XP plus 50 Ore Miner XP. Random drops would need separately defined rates and rules; none are enabled here.','mining guaranteed random yield xp eight'),
 faq('faq-mining-branches','skills','When can I switch Mining branches?','After the current activity completes or is canceled. Ore Miner opens at overall level 10; Gem Prospector and Rare Mineral Extractor at 30. Each branch retains its own XP. Browsing another branch preview does not alter a running activity. Training remains a preview.','mining switch branch ore gem rare mineral cancel'),
 faq('faq-farming-free','skills','Can I farm without runes?','The V1 Wheat activity costs no runes. It still requires a Basic Hoe and a Wheat Seed. Other Farming activities use their listed rune costs. Farming training and acquisition recipes remain previews.','farming wheat free seed hoe'),
 faq('faq-farming-yield','skills','Does Farming yield multiply the listed XP?','No. Yield and XP are separate rewards per completed batch. Bulk Wheat yields 12 and awards 100 Farming XP plus 60 Crop Farming XP, once. Timers are in minutes.','farming harvest yield batch xp twelve 12'),
 faq('faq-farming-branches','skills','Does switching Farming branches reset progress?','No. Crop Farming, Herbalism, and Rare Plant Cultivation keep independent XP totals. Crop Farming opens at overall level 10; the other two at 30. Each branch starts at level 1 and reaches 99 at 125,000 XP. Earlier Farming concepts remain archived with their saved XP.','farming switch branch reset crop herbalism rare plant level'),
 faq('faq-fishing-bundle','skills','Does a Fishing x5 bundle give five times the listed XP?','No. The listed Fishing XP and branch XP are the total reward for one completed batch. Shrimp Bundle x5 awards 90 Fishing XP plus 55 Commercial XP, once per batch. These rewards remain draft values until training is enabled.','fishing commercial batch bundle five 5 xp'),
 faq('faq-fishing-runes','skills','Does beginner Fishing require runes?','Yes. V7 replaces the earlier rune-free Fishing draft. Shrimp requires 1 Air Rune and a Small Net. Other professions still offer rune-free Basic recipe previews.','fishing shrimp air beginner cost'),
 faq('faq-fishing-branches','skills','What happened to River Angler, Deep Sea Fisher, and Legendary Angler?','V7 replaces those paths with Commercial, Treasure, and Trophy Fishing. Commercial starts at Fishing level 10; Treasure and Trophy at level 30. All three begin at branch level 1. Earlier branch progress is retained in the account history and is not reassigned. The V2 branch XP curve is now stored and enforced; branch training remains a preview.','fishing river angler deep sea legendary branch specialization'),
 faq('faq-fishing-branch-xp','skills','Does switching Fishing branches reset my XP?','No. Commercial, Treasure, and Trophy retain separate XP totals and branch levels. Each starts at level 1 with 0 XP and reaches level 99 at 125,000 branch XP. A future specialization activity will award overall Fishing XP plus XP only to its selected branch; Standard Fishing awards no branch XP. You must meet both overall and branch item requirements. One skill or service activity runs at a time, while passive runes continue separately. Training remains a preview.','fishing branch v2 switch reset 125000 125,000 commercial treasure trophy independent'),
 faq('faq-fishing-xp','skills','How much Fishing XP do I need for level 99?','239,164 cumulative Fishing XP. Fishing starts at level 1 with 0 XP. Level 10 needs 184 XP and level 30 needs 1,428 XP. Search “Fishing leveling” for all 99 thresholds. The curve is saved now; Fishing activities remain previews.','fishing leveling 99 mastery 239164 thresholds'),
 faq('faq-fishing-progress','skills','Does my Fishing XP reset when I level up?','No. Total Fishing XP is cumulative. At 20 total XP you are level 2 with 5 of 16 XP toward level 3. At level 99, additional saved XP is retained but the level stops increasing. Specialization XP is tracked separately for Commercial, Treasure, and Trophy, with level 99 at 125,000 XP per branch.','fishing total next level progress bar reset'),
 faq('faq-fishing-start','skills','Why am I Fishing level 1 with zero XP?','Level 1 is the starting level in the overall Fishing V2 curve. All seven professions now start at level 1 under Universal XP Master V1. This does not grant XP, items, runes, or specialization levels.','fishing zero 0 1 starting'),
 faq('faq-level','skills','Why did smithing not raise my Smithing skill?','The current Steel Bar activity grants adventure XP. Profession and specialization training is not activated, so those separate account levels remain unchanged.','xp experience level zero 0'),
 faq('faq-cost','skills','Will viewing recipes or paths spend my runes?','No. Recipe and specialization screens are previews. Viewing them or choosing another path preview spends nothing and does not permanently select a path.','cost path choose reset'),
 faq('faq-device','saving','Will my equipment follow me to another device?','Yes. Equipment, items, game gold, adventure XP, and activities now follow your account alongside rune inventory, wallet links, and skills. Existing players should first open the updated game in their original browser so its old progress can be imported once. The first account save wins; later browser saves are not merged.','lost save sync storage'),
 faq('faq-active','items','Can I run several activities at once?','The current prototype has one active task slot. Complete or cancel that task before starting another. Automatic rune production runs independently.','parallel queue crafting time'),
 faq('faq-supplies','items','What can I do when crafting supplies run out?','The current prototype has no replenishment control for crafting supplies. You can still complete merchant delivery services, manage passive rune production if eligible, and explore skill previews.','empty supplies replenish gather'),
 faq('faq-wallet-change','wallet','Will changing wallets keep my old holding time?','The new wallet is evaluated from its own verified history. Time from different wallets is not combined. Earned rune inventory remains on your player account.','switch unlink change wallet'),
];
export const allGuideEntries=[...guideArticles,...guideFAQs];
const normalize=value=>value.normalize('NFKD').toLowerCase().replace(/[^a-z0-9]+/g,' ').trim();
export function searchGuide(query='',category='all'){
 const ignored=new Set(['a','an','the','i','my','me','we','you','your','to','do','does','is','are','am','can','cant','why','how','what','when','where','and','or','of','for','it','in','on','with','get','s','t']);
 const words=normalize(query).split(' ').filter(word=>word&&!ignored.has(word));
 return allGuideEntries.filter(entry=>{
  if(category==='faq'&&!entry.faq)return false;
  if(category!=='all'&&category!=='faq'&&entry.category!==category)return false;
  const haystack=normalize([entry.title,entry.summary,...entry.paragraphs,entry.keywords,entry.table?entry.table.headers.concat(entry.table.rows.flat().map(cell=>typeof cell==='object'?`${cell.label} ${cell.href}`:cell)).join(' '):''].join(' '));
  return words.every(word=>haystack.includes(word));
 });
}
